    Bug 2048826 - Fix folder pane splitter not working in non-first about3pane tabs. r=mkmelin,freaktechnik


    The isDisabled setter was changed in bug 2008907 from an if/else that
    explicitly removed the disabled attribute for falsy values, to a single
    toggleAttribute() call. When syntheticView is undefined (the normal case),
    this called toggleAttribute("disabled", undefined), which per DOM spec
    toggles the attribute (adds if absent) rather than removing it —
    incorrectly disabling the folder pane splitter in any tab opened after
    the first.

    Fix by going back to the original if/else pattern, and add a test.

    Differential Revision: https://phabricator.services.mozilla.com/D307929

diff --git a/mail/base/content/widgets/pane-splitter.js b/mail/base/content/widgets/pane-splitter.js
index 3d311afd14c..3474c691c0a 100644
--- a/mail/base/content/widgets/pane-splitter.js
+++ b/mail/base/content/widgets/pane-splitter.js
@@ -332,7 +332,7 @@
     }

     set isDisabled(disabled) {
-      this.toggleAttribute("disabled", disabled);
+      this.toggleAttribute("disabled", !!disabled);
     }

     /**
diff --git a/mail/base/test/browser/widgets/browser_paneSplitter.js b/mail/base/test/browser/widgets/browser_paneSplitter.js
index 4951c060101..04d63ff6f94 100644
--- a/mail/base/test/browser/widgets/browser_paneSplitter.js
+++ b/mail/base/test/browser/widgets/browser_paneSplitter.js
@@ -675,3 +675,68 @@ async function subtestCollapseExpand() {

   testRunner.clearCollapseSize();
 }
+
+add_task(async function testIsDisabled() {
+  const splitters = doc.querySelectorAll(`hr[is="pane-splitter"]`);
+  Assert.greater(splitters.length, 0, "should find splitters");
+
+  for (const splitter of splitters) {
+    // Setting to true adds the disabled attribute.
+    splitter.isDisabled = true;
+    Assert.ok(
+      splitter.hasAttribute("disabled"),
+      `${splitter.id}: has disabled attribute`
+    );
+    Assert.ok(splitter.isDisabled, `${splitter.id}: isDisabled returns true`);
+
+    // Setting to false removes it.
+    splitter.isDisabled = false;
+    Assert.ok(
+      !splitter.hasAttribute("disabled"),
+      `${splitter.id}: no disabled attribute`
+    );
+    Assert.ok(!splitter.isDisabled, `${splitter.id}: isDisabled returns false`);
+
+    // Falsy values should remove the attribute.
+    splitter.isDisabled = undefined;
+    Assert.ok(
+      !splitter.hasAttribute("disabled"),
+      `${splitter.id}: undefined removes attribute`
+    );
+    splitter.isDisabled = null;
+    Assert.ok(
+      !splitter.hasAttribute("disabled"),
+      `${splitter.id}: null removes attribute`
+    );
+    splitter.isDisabled = 0;
+    Assert.ok(
+      !splitter.hasAttribute("disabled"),
+      `${splitter.id}: 0 removes attribute`
+    );
+    splitter.isDisabled = "";
+    Assert.ok(
+      !splitter.hasAttribute("disabled"),
+      `${splitter.id}: empty string removes attribute`
+    );
+
+    // Truthy values should add the attribute.
+    splitter.isDisabled = 1;
+    Assert.ok(
+      splitter.hasAttribute("disabled"),
+      `${splitter.id}: 1 adds attribute`
+    );
+    splitter.isDisabled = "false";
+    Assert.ok(
+      splitter.hasAttribute("disabled"),
+      `${splitter.id}: 'false' string adds attribute`
+    );
+    splitter.isDisabled = {};
+    Assert.ok(
+      splitter.hasAttribute("disabled"),
+      `${splitter.id}: object adds attribute`
+    );
+
+    // Clean up.
+    splitter.isDisabled = false;
+  }
+});
